mapper.sql:
FROM ACT_RU_TASK t
LEFT JOIN ACT_HI_PROCINST p ON p.ID_ = t.PROC_INST_ID_
LEFT JOIN ACT_RE_PROCDEF def ON def.ID_ = t.PROC_DEF_ID_
LEFT JOIN ACT_RU_VARIABLE urgency ON urgency.PROC_INST_ID_ = t.PROC_INST_ID_ AND urgency.NAME_ = #{VAR_URGENCY}
LEFT JOIN ACT_RU_VARIABLE sourceUnit ON sourceUnit.PROC_INST_ID_ = t.PROC_INST_ID_ AND sourceUnit.NAME_ = #{VAR_SOURCE_UNIT}
LEFT JOIN ACT_RU_VARIABLE deadline ON deadline.PROC_INST_ID_ = t.PROC_INST_ID_ AND deadline.NAME_ = #{VAR_DEADLINE}

sql.where:
(
    t.ASSIGNEE_ = CAST(#{userId} AS VARCHAR)
    OR EXISTS (
        SELECT 1 FROM ACT_RU_IDENTITYLINK candidateLink
        WHERE candidateLink.TASK_ID_ = t.ID_
          AND candidateLink.TYPE_ = 'candidate'
          AND candidateLink.USER_ID_ = CAST(#{userId} AS VARCHAR)
    )
)
AND t.SUSPENSION_STATE_ = 1
AND NOT EXISTS (
    SELECT 1 FROM ACT_RU_VARIABLE deletedStatus
    WHERE deletedStatus.PROC_INST_ID_ = t.PROC_INST_ID_
      AND deletedStatus.NAME_ = #{VAR_PROCESS_STATUS}
      AND COALESCE(CAST(deletedStatus.LONG_ AS VARCHAR), deletedStatus.TEXT_) = '5'
)
 AND t.NAME_ LIKE CONCAT('%', #{reqVO.name}, '%') 
 AND t.CATEGORY_ = #{reqVO.category} 
 AND def.KEY_ = #{reqVO.processDefinitionKey} 

    AND t.CREATE_TIME_ BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}



        AND p.NAME_ LIKE CONCAT('%', #{keyword}, '%')


 AND t.PROC_INST_ID_ = #{reqVO.processInstanceId} 
 AND COALESCE(CAST(urgency.LONG_ AS VARCHAR), urgency.TEXT_) = CAST(#{reqVO.urgencyDegree} AS VARCHAR) 
 AND LOWER(sourceUnit.TEXT_) LIKE LOWER(CONCAT('%', #{reqVO.sendingUnit}, '%')) 

    AND t.DUE_DATE_ BETWEEN #{reqVO.dueDate[0]} AND #{reqVO.dueDate[1]}


    AND deadline.LONG_ IS NOT NULL
    AND to_timestamp(deadline.LONG_ / 1000) BETWEEN #{reqVO.processDeadline[0]} AND #{reqVO.processDeadline[1]}

mapper.sql:
FROM ACT_HI_TASKINST t
LEFT JOIN ACT_HI_PROCINST p ON p.ID_ = t.PROC_INST_ID_
LEFT JOIN ACT_RE_PROCDEF def ON def.ID_ = t.PROC_DEF_ID_
LEFT JOIN ACT_HI_VARINST urgency ON urgency.PROC_INST_ID_ = t.PROC_INST_ID_ AND urgency.NAME_ = #{VAR_URGENCY}
LEFT JOIN ACT_HI_VARINST sourceUnit ON sourceUnit.PROC_INST_ID_ = t.PROC_INST_ID_ AND sourceUnit.NAME_ = #{VAR_SOURCE_UNIT}
LEFT JOIN ACT_HI_VARINST deadline ON deadline.PROC_INST_ID_ = t.PROC_INST_ID_ AND deadline.NAME_ = #{VAR_DEADLINE}

sql.where:
t.ASSIGNEE_ = CAST(#{userId} AS VARCHAR)
AND t.END_TIME_ IS NOT NULL
AND t.TASK_DEF_KEY_ != #{START_USER_NODE_ID}
AND NOT EXISTS (
    SELECT 1 FROM ACT_HI_VARINST deletedStatus
    WHERE deletedStatus.PROC_INST_ID_ = t.PROC_INST_ID_
      AND deletedStatus.NAME_ = #{VAR_PROCESS_STATUS}
      AND COALESCE(CAST(deletedStatus.LONG_ AS VARCHAR), deletedStatus.TEXT_) = '5'
)
AND NOT EXISTS (
    SELECT 1 FROM ACT_HI_VARINST statusVar
    WHERE statusVar.TASK_ID_ = t.ID_
      AND statusVar.NAME_ = #{TASK_STATUS}
      AND COALESCE(CAST(statusVar.LONG_ AS VARCHAR), statusVar.TEXT_) = '4'
)
 AND t.NAME_ LIKE CONCAT('%', #{reqVO.name}, '%') 

    AND EXISTS (
        SELECT 1 FROM ACT_HI_VARINST statusVar
        WHERE statusVar.TASK_ID_ = t.ID_
          AND statusVar.NAME_ = #{TASK_STATUS}
          AND COALESCE(CAST(statusVar.LONG_ AS VARCHAR), statusVar.TEXT_) = CAST(#{reqVO.status} AS VARCHAR)
    )

 AND t.CATEGORY_ = #{reqVO.category} 
 AND def.KEY_ = #{reqVO.processDefinitionKey} 

    AND t.START_TIME_ BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}



        AND p.NAME_ LIKE CONCAT('%', #{keyword}, '%')


 AND t.PROC_INST_ID_ = #{reqVO.processInstanceId} 
 AND COALESCE(CAST(urgency.LONG_ AS VARCHAR), urgency.TEXT_) = CAST(#{reqVO.urgencyDegree} AS VARCHAR) 
 AND LOWER(sourceUnit.TEXT_) LIKE LOWER(CONCAT('%', #{reqVO.sendingUnit}, '%')) 

    AND t.DUE_DATE_ BETWEEN #{reqVO.dueDate[0]} AND #{reqVO.dueDate[1]}


    AND deadline.LONG_ IS NOT NULL
    AND to_timestamp(deadline.LONG_ / 1000) BETWEEN #{reqVO.processDeadline[0]} AND #{reqVO.processDeadline[1]}

mapper.update:
UPDATE ACT_HI_VARINST
SET LONG_ = #{value},
    TEXT_ = NULL,
    TEXT2_ = NULL
WHERE TASK_ID_ = #{taskId}
  AND NAME_ = #{name}

UPDATE ACT_RU_EXECUTION
SET NAME_ = #{name}
WHERE ID_ = #{processInstanceId}

UPDATE ACT_HI_PROCINST
SET NAME_ = #{name}
WHERE ID_ = #{processInstanceId}
